const rawCosine = $json.ideal_score_cosine;

const min = 0.53;
const max = 0.67;

let adjustedCosine = (rawCosine - min) / (max - min);

adjustedCosine = Math.max(0, Math.min(1, adjustedCosine));

const multipliedCosine = Math.round(adjustedCosine * 100);

return  {
    ideal_score_cosine: adjustedCosine,
    multipliedCosine
  }
;

const item = $json;

const responsibilityScore = item.ai_responsibility_score;
const idealScoreCosine = item.ideal_score_cosine;

const weightResponsibility = 0.7;
const weightCosine = 0.3;

const finalWeightedScore = (responsibilityScore * weightResponsibility) + (idealScoreCosine * weightCosine);

return {
  final_weighted_score: finalWeightedScore,
  responsibility_weighted: responsibilityScore * weightResponsibility,
  ideal_cosine_weighted: idealScoreCosine * weightCosine
};

const data = $json.output; 
let ai_responsibility_score = 1;

if (data.is_ai_orchestration_heavy === "No" && data.is_ai_mentoring_heavy === "No" && data.is_ai_strategy_heavy === "No") {
  ai_responsibility_score = 0;
}

return {
  ai_responsibility_score
};

const weightedScore = $json.final_weighted_score;
const multipliedScore = Math.round(weightedScore * 100);

const passMin = 0.27;

let finalDecision = 'rejected_responsibility';
let applicationStage = 'withdrawn';

if (weightedScore >= passMin) {
  finalDecision = 'passed_responsibility';
  applicationStage = 'lead';
}

return {
  json: {
    ...$json,
    status: finalDecision,
    multipliedScore,
    applicationStage
  }
};

